                                        d="M36.3809 17.4764C35.2228 16.139 33.9195 14.9347 32.4949 13.8857C32.3688 13.7974 32.2186 13.75 32.0646 13.75C31.9106 13.75 31.7604 13.7974 31.6343 13.8857C30.2124 14.9351 28.9115 16.1394 27.7559 17.4764C25.1787 20.436 23.8184 23.556 23.8184 26.4998C23.8184 28.6878 24.6876 30.7862 26.2347 32.3334C27.7819 33.8806 29.8803 34.7498 32.0684 34.7498C34.2564 34.7498 36.3548 33.8806 37.902 32.3334C39.4492 30.7862 40.3184 28.6878 40.3184 26.4998C40.3184 23.556 38.958 20.436 36.3809 17.4764ZM32.0684 33.2498C30.2788 33.2478 28.563 32.536 27.2976 31.2706C26.0321 30.0051 25.3203 28.2894 25.3184 26.4998C25.3184 21.1345 30.5187 16.656 32.0684 15.4373C33.618 16.656 38.8184 21.1326 38.8184 26.4998C38.8164 28.2894 38.1046 30.0051 36.8391 31.2706C35.5737 32.536 33.858 33.2478 32.0684 33.2498ZM37.308 27.3754C37.1136 28.4617 36.5909 29.4623 35.8105 30.2426C35.0301 31.0228 34.0294 31.5452 32.943 31.7395C32.9018 31.746 32.8601 31.7494 32.8184 31.7498C32.6302 31.7497 32.449 31.679 32.3106 31.5516C32.1722 31.4241 32.0867 31.2494 32.0711 31.0619C32.0556 30.8744 32.111 30.6879 32.2265 30.5394C32.342 30.3909 32.5091 30.2912 32.6946 30.2601C34.248 29.9985 35.5662 28.6804 35.8296 27.1242C35.8629 26.928 35.9728 26.7531 36.1351 26.6379C36.2974 26.5228 36.4987 26.4768 36.6949 26.5101C36.8911 26.5434 37.066 26.6533 37.1812 26.8156C37.2963 26.9779 37.3423 27.1792 37.309 27.3754H37.308Z"
